import React, { useEffect, useRef, useState } from "react";
import { motion, useInView } from "framer-motion";
import { STATS } from "./Content";

function Counter({ to, suffix, index }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });
  const started = useRef(false);

  useEffect(() => {
    if (isInView && !started.current) {
      started.current = true;
      const duration = 1800;
      const start = performance.now();
      const tick = (now) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setVal(Math.round(to * eased));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }
  }, [isInView, to]);

  return (
    <motion.span
      ref={ref}
      className="serif block"
      style={{ fontSize: "clamp(32px, 6vw, 48px)", color: "#d4af37", fontWeight: 400 }}
      initial={{ opacity: 0, scale: 0.5 }}
      animate={isInView ? { opacity: 1, scale: 1 } : {}}
      transition={{ delay: index * 0.1, duration: 0.5 }}
    >
      {val.toLocaleString()}{suffix}
    </motion.span>
  );
}

export default function About() {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  return (
    <section id="about" className="section" style={{ background: "#fdf8ed" }}>
      <div className="container mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-16 items-center">
          {/* Left - Text */}
          <motion.div
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6 }}
          >
            <div className="flex items-center gap-3 mb-4">
              <div className="w-8 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
              <span className="overline">The Legacy</span>
            </div>
            <h2 className="section-title">
              A fabric house from Ludhiana, adorning India's grandest{" "}
              <span>celebrations</span>.
            </h2>
            <p className="section-subtitle mt-4">
              For over a decade, D SAJAWAT has been the quiet hand behind some of the country's most exquisite wedding venues. We source, finish and supply premium fabrics - drapes, covers, sashes, florals.
            </p>
            <p className="mt-4" style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.7 }}>
              From a single roll to a banquet's worth - we deliver across India, on time, in finish.
            </p>
          </motion.div>

          {/* Right - Stats */}
          <motion.div
            ref={ref}
            className="stats-grid"
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            {STATS.map((stat, i) => (
              <motion.div
                key={stat.label}
                className="card text-center"
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: 0.3 + i * 0.1 }}
                whileHover={{ y: -4 }}
              >
                <Counter to={stat.value} suffix={stat.suffix} index={i} />
                <span className="overline mt-2 block">{stat.label}</span>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
